import { createHash } from 'node:crypto';
import { gzipSync } from 'node:zlib';
/*
 * Build hashes: the one canonical definition.
 *
 * The server (S1, api/utils/packages/packageBuildHashes.ts) and the package-builder worker (S2,
 * src/hashes.ts) carry ports of these functions. All three must produce the same output for the
 * vectors in __test__/fixtures/hash-vectors.json; that file is copied byte for byte into both
 * repos. Change the algorithm only by bumping the `algorithm` tag and every copy together.
 *
 * Definitions:
 *   H(bytes)        lowercase hex SHA-256. A string is hashed as its UTF-8 bytes.
 *   canonical(v)    JSON with no whitespace. Object keys are sorted by UTF-16 code unit order
 *                   (JavaScript `<` on strings) and keys whose value is `undefined` are dropped.
 *                   Arrays keep their order. Strings and numbers use JSON.stringify.
 *
 *   depsHash    = H(canonical({
 *                   algorithm: 'mint-pkg-deps/1',
 *                   builderVersion,                 // @mintlify/package-builder version
 *                   lockfileKind,                   // 'npm' | 'pnpm'
 *                   lockfile: H(lockfileBytes),     // the lockfile exactly as installed
 *                   dependencies,                   // package.json "dependencies", {} when absent
 *                   registries,                     // docs.json packages.registries as written, {} when absent
 *                 }))
 *
 *   islandsHash = H(canonical({
 *                   algorithm: 'mint-pkg-islands/1',
 *                   islands: [{ id, kind, module: H(module) }] sorted by id,
 *                   snippets: { [path]: H(source) },
 *                   provider: provider ?? null,
 *                   css: css ?? [],
 *                   ssr: ssr ?? true,
 *                   isolation: isolation ?? 'page',
 *                 }))
 *
 *   buildId     = H(depsHash + islandsHash).slice(0, 32)
 *
 * Island `pagePath` and `imports` are left out on purpose: neither changes the build output, and
 * leaving them out lets a build be reused when an unchanged island moves to another page.
 */
export const DEPS_HASH_ALGORITHM = 'mint-pkg-deps/1';
export const ISLANDS_HASH_ALGORITHM = 'mint-pkg-islands/1';
export function sha256Hex(data) {
    return createHash('sha256').update(data).digest('hex');
}
export function sha384Integrity(data) {
    return `sha384-${createHash('sha384').update(data).digest('base64')}`;
}
export function gzipSize(data) {
    return gzipSync(data, { level: 9 }).length;
}
const byCodeUnit = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
export function stableStringify(value) {
    if (value === undefined)
        return 'null';
    if (value === null || typeof value !== 'object')
        return JSON.stringify(value);
    if (Array.isArray(value))
        return `[${value.map(stableStringify).join(',')}]`;
    const entries = Object.entries(value)
        .filter(([, v]) => v !== undefined)
        .sort(([a], [b]) => byCodeUnit(a, b));
    return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${stableStringify(v)}`).join(',')}}`;
}
export function computeDepsHash(input) {
    return sha256Hex(stableStringify({
        algorithm: DEPS_HASH_ALGORITHM,
        builderVersion: input.builderVersion,
        lockfileKind: input.lockfileKind,
        lockfile: sha256Hex(input.lockfileBytes),
        dependencies: input.dependencies,
        registries: input.registries ?? {},
    }));
}
export function computeIslandsHash(input) {
    const islands = input.islands
        .map((island) => ({ id: island.id, kind: island.kind, module: sha256Hex(island.module) }))
        .sort((a, b) => byCodeUnit(a.id, b.id));
    const snippets = Object.fromEntries(Object.entries(input.snippetFiles).map(([path, source]) => [path, sha256Hex(source)]));
    return sha256Hex(stableStringify({
        algorithm: ISLANDS_HASH_ALGORITHM,
        islands,
        snippets,
        provider: input.provider ?? null,
        css: input.css ?? [],
        ssr: input.ssr ?? true,
        isolation: input.isolation ?? 'page',
    }));
}
export function computeBuildId(depsHash, islandsHash) {
    return sha256Hex(depsHash + islandsHash).slice(0, 32);
}
export function islandIdFor(moduleSource) {
    return `i${sha256Hex(moduleSource).slice(0, 16)}`;
}
export function islandPrefix(id) {
    return `mi-${id}-`;
}
